package app.voiceflow;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.security.cert.Certificate;
import java.util.*;
import javax.net.ssl.HttpsURLConnection;

/** Native settings/timeline verification with synthetic history and intercepted HTTPS. */
public final class AppScreensTest extends Instrumentation {
    private Activity main;
    private static final List<JSONObject> requests=Collections.synchronizedList(new ArrayList<>());
    private static String today;
    public void onCreate(Bundle args){super.onCreate(args);start();}
    public void onStart(){Bundle result=new Bundle();Context context=getTargetContext();android.content.SharedPreferences prefs=Store.prefs(context);Map<String,?> saved=prefs.getAll();String oldKey=Vault.get(context);try{
        URL.setURLStreamHandlerFactory(protocol->protocol.equals("https")?new URLStreamHandler(){protected URLConnection openConnection(URL url){return new Mock(url);}}:null);
        Calendar day=Calendar.getInstance();day.set(Calendar.HOUR_OF_DAY,8);day.set(Calendar.MINUTE,45);day.set(Calendar.SECOND,0);long morning=day.getTimeInMillis();today=HistoryDays.key(morning,TimeZone.getDefault());day.set(Calendar.HOUR_OF_DAY,15);day.set(Calendar.MINUTE,20);long afternoon=day.getTimeInMillis();day.add(Calendar.DAY_OF_YEAR,-1);day.set(Calendar.HOUR_OF_DAY,19);long yesterday=day.getTimeInMillis();
        JSONArray history=new JSONArray().put(item(afternoon,"Plan compact settings with short labels and daily summaries using the selected cleanup model.")).put(item(morning,"Discussed a smaller floating mic and vertical controls. The normal keyboard should stay hidden until needed.")).put(item(yesterday,"Reviewed direct input insertion and automatic hiding. Keep the dictation interface out of the way."));
        prefs.edit().putString("history",history.toString()).remove("history_summaries").putString("engine","cloud").putString("language","en-US").putString("polish_model",CloudApi.DEFAULT_POLISH).putString("transcribe_model",CloudApi.DEFAULT_TRANSCRIBE).putString("api_base",CloudApi.DEFAULT_BASE).putString("bubble_size","small").putBoolean("daily_summaries",true).commit();Vault.set(context,"fixture-only-key");
        setInTouchMode(true);main=startActivitySync(new Intent().setClassName("app.voiceflow","app.voiceflow.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));waitForIdleSync();waitRecaps(2);check(requests.size()==2,"Default History did not generate one recap per missing day");check(requests.get(0).getString("model").equals(CloudApi.DEFAULT_POLISH),"Default recap model mismatch");check(description("Hide timeline for "+today)!=null,"History was not the default screen");assertTimelineOrder(afternoon,morning);assertNavigation();capture("history-preview.png");openSettings();check(description("Back to history")!=null,"Settings has no back-to-history control");check(findClickableText("Google Drive backup")!=null,"Visible Google Drive backup action missing");
        String[] groups={"Setup","Floating controls","Speech","Cleanup","Dictionary","API connection","Privacy & history"};for(String group:groups){View header=description(group+",");check(header!=null,"Settings section missing: "+group);if(header.getContentDescription().toString().endsWith("expanded"))click(header);}
        check(prefs.getString("polish_model","").equals(CloudApi.DEFAULT_POLISH) && prefs.getString("transcribe_model","").equals(CloudApi.DEFAULT_TRANSCRIBE) && prefs.getString("engine","").equals("cloud"),"Opening Settings changed provider preferences");
        click(description("Floating controls,"));Spinner size=(Spinner)description("Bubble size");runOnMainSync(()->size.setSelection(1));waitSetting(prefs,"bubble_size","medium");check(description("Floating controls,").getContentDescription().toString().contains("Medium"),"Section summary did not refresh");runOnMainSync(()->size.setSelection(0));waitSetting(prefs,"bubble_size","small");click(description("Floating controls,"));capture("settings-preview.png");
        backToHistory();waitRecaps(2);check(requests.size()==2,"Expected one request per missing day");check(requests.get(0).getString("model").equals(CloudApi.DEFAULT_POLISH),"Default recap model mismatch");check(description("Hide timeline for "+today)!=null,"Today's timeline was not expanded");capture("history-preview.png");
        click(description("Hide timeline for "+today));openSettings();backToHistory();waitRecaps(2);check(requests.size()==2,"Cached history made extra API requests");check(description("Show timeline for "+today)!=null,"Collapsed timeline did not stay collapsed");
        openSettings();click(description("Cleanup,"));Spinner model=(Spinner)description("AI model");runOnMainSync(()->model.setSelection(1));waitSetting(prefs,"polish_model","openai/gpt-oss-120b");backToHistory();waitRecaps(2);check(requests.size()==4 && requests.get(3).getString("model").equals("openai/gpt-oss-120b"),"Changing cleanup model did not refresh recaps with selected model");
        long extra=afternoon+60000;JSONArray changed=new JSONArray(prefs.getString("history","[]"));changed.put(item(extra,"Decided to test the update on my phone."));prefs.edit().putString("history",changed.toString()).commit();refreshHistory();waitRecaps(2);assertTimelineOrder(extra,afternoon);check(requests.size()==5,"A new entry did not refresh only the changed day");check(requests.get(4).getJSONArray("messages").getJSONObject(1).getString("content").contains("test the update on my phone"),"Recap omitted new source text");
        Store.delete(context,extra);check(new JSONObject(prefs.getString("history_summaries","{}")).optJSONObject(today)==null,"Deleted entry remained in cached recap");
        prefs.edit().putString("engine","offline").remove("history_summaries").commit();refreshHistory();Thread.sleep(400);check(requests.size()==5,"On-device mode generated a recap request");
        result.putString("result","PASS: History landing screen, top Settings gear and back control, no bottom navigation, newest-first native timelines, visible backup action, compact settings, preserved preferences, live section summaries, selected-model summaries, cached reopen, model/content invalidation, deletion cleanup, and offline privacy. Native previews use synthetic history and mock HTTPS.");
    }catch(Throwable error){result.putString("failure",error.toString());}finally{
        if(main!=null)runOnMainSync(()->main.finish());try{Vault.set(context,oldKey);}catch(Exception ignored){}
        android.content.SharedPreferences.Editor edit=prefs.edit().clear();for(Map.Entry<String,?> item:saved.entrySet()){Object value=item.getValue();if(value instanceof String)edit.putString(item.getKey(),(String)value);else if(value instanceof Boolean)edit.putBoolean(item.getKey(),(Boolean)value);else if(value instanceof Integer)edit.putInt(item.getKey(),(Integer)value);else if(value instanceof Long)edit.putLong(item.getKey(),(Long)value);else if(value instanceof Float)edit.putFloat(item.getKey(),(Float)value);}edit.commit();
    }finish(result.containsKey("failure")?Activity.RESULT_CANCELED:Activity.RESULT_OK,result);}
    private JSONObject item(long id,String text)throws Exception{return new JSONObject().put("id",id).put("text",text).put("raw",text).put("words",Cleaner.words(text));}
    private void check(boolean okay,String error)throws Exception{if(!okay)throw new Exception(error);}
    private View description(String prefix){View[] found=new View[1];runOnMainSync(()->found[0]=find(main.getWindow().getDecorView(),prefix,null));return found[0];}
    private View find(View view,String description,String text){if(description!=null && view.getContentDescription()!=null && view.getContentDescription().toString().startsWith(description))return view;if(text!=null && view instanceof TextView && ((TextView)view).getText().toString().equals(text) && view.isClickable())return view;if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++){View child=find(group.getChildAt(i),description,text);if(child!=null)return child;}}return null;}
    private void click(View view)throws Exception{check(view!=null,"Missing native control");runOnMainSync(()->view.performClick());waitForIdleSync();}
    private View findClickableText(String text){View[] found=new View[1];runOnMainSync(()->found[0]=find(main.getWindow().getDecorView(),null,text));return found[0];}
    private void openSettings()throws Exception{click(description("Settings"));View back=description("Back to history");check(back!=null && back.getWidth()>=Ui.dp(main,48) && back.getHeight()>=Ui.dp(main,48),"Settings back touch target is too small");}
    private void backToHistory()throws Exception{click(description("Back to history"));}
    private void refreshHistory()throws Exception{openSettings();backToHistory();}
    private void assertNavigation()throws Exception{
        View gear=description("Settings");check(gear instanceof ImageButton,"Settings is not a gear button");check(gear.getWidth()>=Ui.dp(main,48) && gear.getHeight()>=Ui.dp(main,48),"Settings touch target is too small");
        check(findClickableText("Speak")==null && findClickableText("History")==null && findClickableText("Settings")==null,"Obsolete navigation tabs remain");
        boolean[] okay={false};runOnMainSync(()->{ViewGroup mast=(ViewGroup)gear.getParent();okay[0]=mast.indexOfChild(gear)==mast.getChildCount()-1;View frame=(View)mast.getParent();ViewGroup shell=(ViewGroup)frame.getParent();okay[0]&=frame instanceof FrameLayout && shell.indexOfChild(frame)==0 && shell.getChildCount()==2 && shell.getChildAt(1) instanceof ScrollView;});check(okay[0],"Settings is not at top right or bottom navigation still exists");
    }
    private void assertTimelineOrder(long newer,long older)throws Exception{
        View newest=description("Open dictation at "+java.text.DateFormat.getTimeInstance(java.text.DateFormat.SHORT).format(new Date(newer))+": "),previous=description("Open dictation at "+java.text.DateFormat.getTimeInstance(java.text.DateFormat.SHORT).format(new Date(older))+": ");check(newest!=null && previous!=null,"Expected dictations are missing from timeline");boolean[] okay={false};runOnMainSync(()->{okay[0]=newest.getParent()==previous.getParent();if(okay[0])okay[0]=((ViewGroup)newest.getParent()).indexOfChild(newest)<((ViewGroup)previous.getParent()).indexOfChild(previous);});check(okay[0],"Native timeline is not newest first");
    }
    private void waitSetting(android.content.SharedPreferences prefs,String key,String expected)throws Exception{long end=SystemClock.elapsedRealtime()+10000;while(SystemClock.elapsedRealtime()<end){if(expected.equals(prefs.getString(key,""))){waitForIdleSync();return;}Thread.sleep(100);}throw new Exception("Setting did not change: "+key);}
    private void waitRecaps(int count)throws Exception{long end=SystemClock.elapsedRealtime()+20000;while(SystemClock.elapsedRealtime()<end){String data=Store.get(getTargetContext(),"history_summaries","{}");JSONObject cache=new JSONObject(data);boolean current=cache.length()==count;String model=Store.get(getTargetContext(),"polish_model",CloudApi.DEFAULT_POLISH);for(HistoryDays.Day day:HistoryDays.group(entries(),TimeZone.getDefault()))if(DailySummaryCache.get(getTargetContext(),day,model,CloudApi.DEFAULT_BASE).isEmpty())current=false;if(current){waitForIdleSync();return;}Thread.sleep(100);}throw new Exception("Daily summaries did not complete");}
    private List<HistoryDays.Entry> entries(){List<HistoryDays.Entry> list=new ArrayList<>();JSONArray all=Store.history(getTargetContext());for(int i=0;i<all.length();i++){JSONObject item=all.optJSONObject(i);list.add(new HistoryDays.Entry(item.optLong("id"),item.optString("text"),item.optInt("words")));}return list;}
    private void capture(String name)throws Exception{Throwable[] failed=new Throwable[1];runOnMainSync(()->{try{View decor=main.getWindow().getDecorView();Bitmap bitmap=Bitmap.createBitmap(decor.getWidth(),decor.getHeight(),Bitmap.Config.ARGB_8888);decor.draw(new Canvas(bitmap));try(FileOutputStream out=new FileOutputStream(getTargetContext().getFilesDir()+"/"+name)){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();}catch(Throwable e){failed[0]=e;}});if(failed[0]!=null)throw new Exception(failed[0]);}
    private static final class Mock extends HttpsURLConnection {
        final ByteArrayOutputStream out=new ByteArrayOutputStream();Mock(URL url){super(url);}public void connect(){}public void disconnect(){}public boolean usingProxy(){return false;}public String getCipherSuite(){return "fixture";}public Certificate[] getLocalCertificates(){return null;}public Certificate[] getServerCertificates(){return null;}public OutputStream getOutputStream(){return out;}public int getResponseCode(){return 200;}
        public InputStream getInputStream()throws IOException{try{JSONObject request=new JSONObject(out.toString("UTF-8"));requests.add(request);String source=request.getJSONArray("messages").getJSONObject(1).getString("content");String text=source.contains(today)?"Planned a smaller floating mic with vertical controls, compact settings, and daily recaps using the selected AI model. The normal keyboard should stay hidden until needed.":"Reviewed direct text insertion and automatic hiding to keep dictation clear and unobtrusive.";return new ByteArrayInputStream(new JSONObject().put("choices",new JSONArray().put(new JSONObject().put("message",new JSONObject().put("content",text)))).toString().getBytes("UTF-8"));}catch(Exception e){throw new IOException(e);}}
    }
}
